import React, { useState, useRef, useEffect } from 'react';
import {
  Container,
  Box,
  AppBar,
  Toolbar,
  Typography,
  TextField,
  Button,
  Paper,
  Select,
  MenuItem,
  FormControl,
  InputLabel,
  Card,
  CardContent,
  CircularProgress,
  Chip,
  Grid,
  Divider,
  Alert
} from '@mui/material';
import {
  Send as SendIcon,
  Download as DownloadIcon,
  Assessment as AssessmentIcon,
  Science as ScienceIcon,
  AutoAwesome as AIIcon,
  Home as HomeIcon
} from '@mui/icons-material';
import ReactMarkdown from 'react-markdown';
import AgentResultDisplay from './components/AgentResultDisplay';
import axios from 'axios';
import LandingPage from './LandingPage';
import './App.css';

const API_URL = process.env.REACT_APP_API_URL || 'http://localhost:8000';

function App() {
  // Initialize state from localStorage to persist across refreshes
  const [showLanding, setShowLanding] = useState(() => {
    return localStorage.getItem('has_visited_app') !== 'true';
  });

  const [query, setQuery] = useState('');
  const [provider, setProvider] = useState('openai');
  const [loading, setLoading] = useState(false);
  const [results, setResults] = useState(null);
  const [usageStats, setUsageStats] = useState(null);
  const [error, setError] = useState(null);
  const messagesEndRef = useRef(null);

  const handleStart = () => {
    localStorage.setItem('has_visited_app', 'true');
    setShowLanding(false);
  };

  const handleBackToHome = () => {
    localStorage.removeItem('has_visited_app');
    setShowLanding(true);
  };

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
    fetchUsageStats();
  }, [results]);

  const fetchUsageStats = async () => {
    try {
      const response = await axios.get(`${API_URL}/api/usage`);
      setUsageStats(response.data);
    } catch (err) {
      console.error('Error fetching usage stats:', err);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!query.trim()) return;

    setLoading(true);
    setError(null);

    try {
      const response = await axios.post(`${API_URL}/api/query`, {
        query: query,
        provider: provider
      });

      setResults(response.data.data);
      setUsageStats(response.data.usage_stats);
    } catch (err) {
      setError(err.response?.data?.detail || 'An error occurred');
    } finally {
      setLoading(false);
    }
  };

  const downloadReport = async () => {
    if (!results?.report_path) return;

    const filename = results.report_path.split('/').pop();
    window.open(`${API_URL}/api/reports/${filename}`, '_blank');
  };

  const sampleQueries = [
    // Drug Repurposing & Research
    "Analyze Metformin repurposing opportunities for cardiovascular diseases",
    "Emerging therapeutic applications of GLP-1 agonists beyond diabetes",
    "Drug repurposing candidates for Alzheimer's from cancer therapies",
    // Patent Landscape
    "Patent landscape for CAR-T cell therapy in solid tumors",
    "Companies with most patents for mRNA vaccine delivery systems",
    "Patent expiry analysis for top biologics in US market",
    // Clinical Trials
    "Phase 3 clinical trials for lung cancer immunotherapy",
    "Latest CRISPR-based gene therapy clinical trials",
    "Clinical trials comparison: Ozempic vs Mounjaro vs Zepbound",
    "Orphan drug trials for rare pediatric diseases in India",
    // Market Intelligence
    "US Medicare pricing trends for diabetes medications 2020-2024",
    "Generic vs Branded statin pricing in India",
    "Biosimilars market size and forecast in oncology",
    // Trade & Supply Chain
    "Pharmaceutical API import/export trends: India to US",
    "Largest exporters of vaccine raw materials globally",
    // Multi-Domain Queries
    "Comprehensive analysis of Pembrolizumab: patents, trials, pricing",
    "White space opportunities in NASH therapeutic landscape",
    "Antibiotic resistance: pipeline, patents, and global trade"
  ];

  if (showLanding) {
    return <LandingPage onStart={handleStart} />;
  }

  return (
    <Box sx={{ flexGrow: 1, minHeight: '100vh', bgcolor: 'transparent' }}>
      <AppBar position="fixed" className="dashboard-header">
        <Toolbar>
          <Button
            onClick={handleBackToHome}
            sx={{ mr: 1, minWidth: 'auto', color: '#2563EB' }}
          >
            <HomeIcon />
          </Button>
          <Typography variant="h6" component="div" className="dashboard-title" sx={{ flexGrow: 1, cursor: 'pointer' }} onClick={handleBackToHome}>
            MedCore Research Platform
          </Typography>
          <Chip
            icon={<AIIcon />}
            label={provider === 'openai' ? 'ChatGPT' : provider === 'gemini' ? 'Gemini 2.5' : 'Groq LLaMA 3'}
            sx={{
              mr: 2,
              bgcolor: '#EFF6FF',
              color: '#2563EB',
              fontWeight: 600,
              '& .MuiChip-icon': { color: '#2563EB' }
            }}
          />
          {usageStats && (
            <Chip
              label={`$${usageStats.total_cost_usd.toFixed(4)}`}
              size="small"
              sx={{
                bgcolor: '#DCFCE7',
                color: '#16A34A',
                fontWeight: 600
              }}
            />
          )}
        </Toolbar>
      </AppBar>
      <Toolbar /> {/* Spacer for fixed AppBar */}

      <Container maxWidth="xl" sx={{ mt: 4, mb: 4 }}>
        <Grid container spacing={3}>
          <Grid item xs={12} md={4}>
            <Card className="medcore-card" elevation={0}>
              <CardContent sx={{ p: 3 }}>
                <Typography variant="h6" gutterBottom sx={{ display: 'flex', alignItems: 'center', fontWeight: 600, color: '#1E40AF' }}>
                  <AssessmentIcon sx={{ mr: 1 }} />
                  Research Query
                </Typography>

                <Box component="form" onSubmit={handleSubmit} sx={{ mt: 3 }}>
                  <FormControl fullWidth sx={{ mb: 2 }}>
                    <InputLabel>AI Provider</InputLabel>
                    <Select
                      value={provider}
                      label="AI Provider"
                      onChange={(e) => setProvider(e.target.value)}
                      sx={{ borderRadius: 2 }}
                    >
                      <MenuItem value="openai">ChatGPT (GPT-4)</MenuItem>
                      <MenuItem value="gemini">Gemini 2.5 Flash</MenuItem>
                      <MenuItem value="groq">Groq (LLaMA 3 70B)</MenuItem>
                    </Select>
                  </FormControl>

                  <TextField
                    fullWidth
                    multiline
                    rows={6}
                    value={query}
                    onChange={(e) => setQuery(e.target.value)}
                    placeholder="Enter your pharmaceutical research query..."
                    variant="outlined"
                    sx={{
                      mb: 2,
                      '& .MuiOutlinedInput-root': {
                        borderRadius: 2,
                        bgcolor: '#F8FAFC'
                      }
                    }}
                  />

                  <Button
                    type="submit"
                    variant="contained"
                    fullWidth
                    size="large"
                    disabled={loading || !query.trim()}
                    startIcon={loading ? <CircularProgress size={20} color="inherit" /> : <SendIcon />}
                    className="medcore-btn"
                    sx={{ bgcolor: '#2563EB', '&:hover': { bgcolor: '#1D4ED8' } }}
                  >
                    {loading ? 'Researching...' : 'Start Research'}
                  </Button>
                </Box>

                <Divider sx={{ my: 3 }} />

                <Typography variant="subtitle2" gutterBottom sx={{ color: '#64748B', fontWeight: 600 }}>
                  Sample Queries:
                </Typography>
                {sampleQueries.map((sq, idx) => (
                  <Chip
                    key={idx}
                    label={sq}
                    onClick={() => setQuery(sq)}
                    sx={{
                      m: 0.5,
                      borderRadius: '8px',
                      bgcolor: '#F1F5F9',
                      '&:hover': { bgcolor: '#E2E8F0' }
                    }}
                    size="small"
                  />
                ))}

                {usageStats && (
                  <Box sx={{ mt: 3 }}>
                    <Typography variant="subtitle2" gutterBottom>
                      Usage Statistics:
                    </Typography>
                    <Typography variant="body2" color="text.secondary">
                      OpenAI: {usageStats.tokens_used.openai} tokens (${usageStats.total_cost.openai.toFixed(4)})
                    </Typography>
                    <Typography variant="body2" color="text.secondary">
                      Gemini: {usageStats.tokens_used.gemini} tokens (${usageStats.total_cost.gemini.toFixed(4)})
                    </Typography>
                    <Typography variant="body2" color="text.secondary">
                      Groq: {usageStats.tokens_used.groq || 0} tokens (${(usageStats.total_cost.groq || 0).toFixed(4)})
                    </Typography>
                  </Box>
                )}
              </CardContent>
            </Card>
          </Grid>

          <Grid item xs={12} md={8}>
            <Card className="medcore-card" elevation={0} sx={{ minHeight: '600px' }}>
              <CardContent sx={{ p: 4 }}>
                {error && (
                  <Alert severity="error" sx={{ mb: 2, borderRadius: 2 }}>
                    {error}
                  </Alert>
                )}

                {!results && !loading && (
                  <Box sx={{ textAlign: 'center', py: 12 }}>
                    <ScienceIcon sx={{ fontSize: 80, color: '#E2E8F0', mb: 2 }} />
                    <Typography variant="h5" sx={{ color: '#94A3B8', fontWeight: 600 }}>
                      Ready to Research
                    </Typography>
                    <Typography variant="body2" color="text.secondary" sx={{ mt: 1 }}>
                      Enter a query to start multi-agent pharmaceutical research
                    </Typography>
                  </Box>
                )}

                {loading && (
                  <Box sx={{ textAlign: 'center', py: 8 }}>
                    <CircularProgress size={60} />
                    <Typography variant="h6" sx={{ mt: 2 }}>
                      AI Agents Working...
                    </Typography>
                    <Typography variant="body2" color="text.secondary">
                      Analyzing clinical trials, patents, market data, and scientific literature
                    </Typography>
                  </Box>
                )}

                {results && (
                  <Box>
                    <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
                      <Typography variant="h6">
                        Research Results
                      </Typography>
                      {results.report_path && (
                        <Button
                          variant="contained"
                          startIcon={<DownloadIcon />}
                          onClick={downloadReport}
                          size="small"
                        >
                          Download Report
                        </Button>
                      )}
                    </Box>

                    <Paper elevation={1} sx={{ p: 2, mb: 2, bgcolor: '#f5f5f5' }}>
                      <Typography variant="subtitle2" color="primary">
                        Query: {results.query}
                      </Typography>
                      <Typography variant="body2" color="text.secondary">
                        Intent: {results.plan.intent}
                      </Typography>
                    </Paper>

                    <Paper elevation={1} sx={{ p: 3, mb: 2 }}>
                      <Typography variant="h6" gutterBottom>
                        Executive Summary
                      </Typography>
                      <Box className="markdown-content">
                        <ReactMarkdown>{results.synthesis}</ReactMarkdown>
                      </Box>
                    </Paper>

                    <Typography variant="h6" gutterBottom sx={{ mt: 3 }}>
                      Detailed Agent Findings
                    </Typography>

                    {Object.entries(results.agent_results).map(([agentName, agentResult]) => (
                      <Paper key={agentName} elevation={1} sx={{ p: 2, mb: 2 }}>
                        <Typography variant="subtitle1" color="primary" gutterBottom>
                          {agentName.replace(/_/g, ' ').toUpperCase()}
                        </Typography>
                        <AgentResultDisplay data={agentResult.data} />
                      </Paper>
                    ))}

                    <div ref={messagesEndRef} />
                  </Box>
                )}
              </CardContent>
            </Card>
          </Grid>
        </Grid>
      </Container>
    </Box>
  );
}

export default App;
